use std::collections::HashSet;
use std::error::Error;
use std::fmt::Write as _;
use std::fs;
use std::path::Path;

use serde::Deserialize;

const GENERATED_HEADER_RUST: &str =
    "// @generated by `cargo xtask generate` from `spec/`. DO NOT EDIT.\n\n";
const GENERATED_HEADER_PHP: &str =
    "// @generated by `cargo xtask generate` from `spec/`. DO NOT EDIT.\n";

#[derive(Debug, Deserialize)]
struct RootTargetSpec {
    target: TargetSpec,
    chunk: ChunkSpec,
    block_state: BlockStateSpec,
}

#[derive(Debug, Deserialize)]
struct TargetSpec {
    game_version: String,
    game_protocol: i32,
    raknet_protocol: u8,
}

#[derive(Debug, Deserialize)]
struct ChunkSpec {
    edge: usize,
    height: usize,
}

#[derive(Debug, Deserialize)]
struct BlockStateSpec {
    data_bits: u32,
}

#[derive(Debug, Deserialize)]
struct BlocksSpec {
    block: Vec<BlockSpec>,
}

#[derive(Debug, Deserialize)]
struct BlockSpec {
    id: u8,
    name: String,
    asset: Option<String>,
    #[serde(default = "default_public")]
    public: bool,
}

#[derive(Debug, Deserialize)]
struct BiomesSpec {
    biome: Vec<BiomeSpec>,
}

#[derive(Debug, Deserialize)]
struct BiomeSpec {
    id: u8,
    name: String,
    display: String,
    color: u32,
}

fn default_public() -> bool {
    true
}

struct GeneratedFile {
    path: &'static str,
    contents: String,
}

pub fn run(root: &Path, check: bool) -> Result<(), Box<dyn Error>> {
    let target: RootTargetSpec = read_toml(&root.join("spec/target.toml"))?;
    let blocks: BlocksSpec = read_toml(&root.join("spec/blocks.toml"))?;
    let biomes: BiomesSpec = read_toml(&root.join("spec/biomes.toml"))?;
    validate(&target, &blocks, &biomes)?;

    let outputs = generate(&target, &blocks, &biomes)?;
    let mut stale = Vec::new();
    for output in outputs {
        let path = root.join(output.path);
        if check {
            if fs::read_to_string(&path).ok().as_deref() != Some(output.contents.as_str()) {
                stale.push(output.path);
            }
        } else {
            if let Some(parent) = path.parent() {
                fs::create_dir_all(parent)?;
            }
            fs::write(path, output.contents)?;
        }
    }

    if !stale.is_empty() {
        let paths = stale.join("\n  ");
        return Err(format!(
            "generated target sources are stale:\n  {paths}\nrun: cargo xtask generate"
        )
        .into());
    }

    if check {
        println!("target generation: current");
    } else {
        println!("target generation: updated");
    }
    Ok(())
}

fn read_toml<T: for<'de> Deserialize<'de>>(path: &Path) -> Result<T, Box<dyn Error>> {
    Ok(toml::from_str(&fs::read_to_string(path)?)?)
}

fn validate(
    target: &RootTargetSpec,
    blocks: &BlocksSpec,
    biomes: &BiomesSpec,
) -> Result<(), Box<dyn Error>> {
    let versions: Vec<_> = target.target.game_version.split('.').collect();
    if versions.len() != 3 || versions.iter().any(|part| part.parse::<u8>().is_err()) {
        return Err("target.game_version must be exactly three u8 components".into());
    }
    if target.target.game_protocol <= 0 || target.chunk.edge == 0 || target.chunk.height == 0 {
        return Err("protocol and chunk dimensions must be positive".into());
    }
    if !target.chunk.height.is_multiple_of(target.chunk.edge) {
        return Err("chunk height must be an exact multiple of the section edge".into());
    }
    if target.block_state.data_bits == 0 || target.block_state.data_bits > 8 {
        return Err("block_state.data_bits must be in 1..=8".into());
    }

    let mut last = None;
    let mut ids = HashSet::new();
    let mut names = HashSet::new();
    let mut assets = HashSet::new();
    for block in &blocks.block {
        if last.is_some_and(|previous| block.id <= previous) {
            return Err("block entries must be strictly ordered by id".into());
        }
        last = Some(block.id);
        if !ids.insert(block.id) || !names.insert(block.name.as_str()) {
            return Err(format!("duplicate block id/name near {}", block.name).into());
        }
        validate_snake_name("block", &block.name)?;
        if block.public {
            let Some(asset) = block.asset.as_deref() else {
                return Err(format!("public block {} requires an asset name", block.name).into());
            };
            if !assets.insert(asset) {
                return Err(format!("duplicate public block asset name {asset}").into());
            }
        } else if block.asset.is_some() {
            return Err(format!(
                "internal block {} must not expose a public asset name",
                block.name
            )
            .into());
        }
    }

    last = None;
    ids.clear();
    names.clear();
    for biome in &biomes.biome {
        if last.is_some_and(|previous| biome.id <= previous) {
            return Err("biome entries must be strictly ordered by id".into());
        }
        last = Some(biome.id);
        if !ids.insert(biome.id) || !names.insert(biome.name.as_str()) {
            return Err(format!("duplicate biome id/name near {}", biome.name).into());
        }
        validate_snake_name("biome", &biome.name)?;
        if biome.display.is_empty() || biome.color > 0x00ff_ffff {
            return Err(format!("invalid biome metadata for {}", biome.name).into());
        }
    }
    Ok(())
}

fn validate_snake_name(kind: &str, name: &str) -> Result<(), Box<dyn Error>> {
    let valid = !name.is_empty()
        && name
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_')
        && !name.starts_with('_')
        && !name.ends_with('_')
        && !name.contains("__");
    if valid {
        Ok(())
    } else {
        Err(format!("{kind} name must be lower_snake_case: {name}").into())
    }
}

fn generate(
    target: &RootTargetSpec,
    blocks: &BlocksSpec,
    biomes: &BiomesSpec,
) -> Result<Vec<GeneratedFile>, Box<dyn Error>> {
    Ok(vec![
        GeneratedFile {
            path: "native/target/src/generated/mod.rs",
            contents: format!(
                "{GENERATED_HEADER_RUST}pub(super) mod biomes;\npub(super) mod blocks;\npub(super) mod target;\n"
            ),
        },
        GeneratedFile {
            path: "native/target/src/generated/target.rs",
            contents: rust_target(target)?,
        },
        GeneratedFile {
            path: "native/target/src/generated/blocks.rs",
            contents: rust_blocks(blocks)?,
        },
        GeneratedFile {
            path: "native/target/src/generated/biomes.rs",
            contents: rust_biomes(biomes)?,
        },
        GeneratedFile {
            path: "src/Internal/Target.php",
            contents: php_target(target)?,
        },
        GeneratedFile {
            path: "src/World/WorldBounds.php",
            contents: php_world_bounds(target)?,
        },
        GeneratedFile {
            path: "src/World/BlockType.php",
            contents: php_block_type(blocks)?,
        },
        GeneratedFile {
            path: "src/World/BiomeId.php",
            contents: php_biome_id(biomes)?,
        },
        GeneratedFile {
            path: "src/World/BiomeCatalog.php",
            contents: php_biome_catalog(biomes)?,
        },
    ])
}

fn rust_target(spec: &RootTargetSpec) -> Result<String, Box<dyn Error>> {
    let version = version_parts(&spec.target.game_version)?;
    let state_bits = 8 + spec.block_state.data_bits;
    let max_state = (1_u32 << state_bits) - 1;
    let mut out = String::from(GENERATED_HEADER_RUST);
    writeln!(
        out,
        "pub const GAME_VERSION: &str = {:?};",
        spec.target.game_version
    )?;
    writeln!(out, "pub const GAME_VERSION_MAJOR: u8 = {};", version[0])?;
    writeln!(out, "pub const GAME_VERSION_MINOR: u8 = {};", version[1])?;
    writeln!(out, "pub const GAME_VERSION_PATCH: u8 = {};", version[2])?;
    writeln!(
        out,
        "pub const GAME_PROTOCOL: i32 = {};",
        spec.target.game_protocol
    )?;
    writeln!(
        out,
        "pub const RAKNET_PROTOCOL: u8 = {};",
        spec.target.raknet_protocol
    )?;
    writeln!(
        out,
        "pub const BLOCK_DATA_BITS: u32 = {};",
        spec.block_state.data_bits
    )?;
    writeln!(
        out,
        "pub const MAX_BLOCK_STATE_ID: u16 = 0x{max_state:04x};"
    )?;
    writeln!(out, "\npub struct ChunkShape;\n")?;
    writeln!(out, "impl ChunkShape {{")?;
    writeln!(out, "    pub const EDGE: usize = {};", spec.chunk.edge)?;
    writeln!(out, "    pub const HEIGHT: usize = {};", spec.chunk.height)?;
    writeln!(out, "    pub const SECTION_EDGE: usize = Self::EDGE;")?;
    writeln!(
        out,
        "    pub const SECTION_COUNT: usize = Self::HEIGHT / Self::SECTION_EDGE;"
    )?;
    writeln!(
        out,
        "    pub const COLUMN_COUNT: usize = Self::EDGE * Self::EDGE;"
    )?;
    writeln!(
        out,
        "    pub const BLOCK_COUNT: usize = Self::COLUMN_COUNT * Self::HEIGHT;"
    )?;
    writeln!(
        out,
        "    pub const NIBBLE_BYTES: usize = Self::BLOCK_COUNT / 2;"
    )?;
    writeln!(out, "}}")?;
    Ok(out)
}

fn rust_blocks(spec: &BlocksSpec) -> Result<String, Box<dyn Error>> {
    let public: Vec<_> = spec.block.iter().filter(|block| block.public).collect();
    let internal: Vec<_> = spec.block.iter().filter(|block| !block.public).collect();
    let mut out = String::from(GENERATED_HEADER_RUST);
    out.push_str("use crate::BlockId;\n\n");
    out.push_str("impl BlockId {\n");
    for block in &spec.block {
        writeln!(
            out,
            "    pub const {}: Self = Self({});",
            screaming(&block.name),
            block.id
        )?;
    }
    writeln!(
        out,
        "\n    #[must_use]\n    pub const fn is_public(self) -> bool {{"
    )?;
    writeln!(
        out,
        "        matches!(self.0, {})",
        rust_ranges(&public.iter().map(|b| b.id).collect::<Vec<_>>())
    )?;
    writeln!(out, "    }}")?;
    writeln!(
        out,
        "\n    #[must_use]\n    pub const fn is_world_supported(self) -> bool {{"
    )?;
    writeln!(
        out,
        "        matches!(self.0, {})",
        rust_ranges(&spec.block.iter().map(|b| b.id).collect::<Vec<_>>())
    )?;
    writeln!(out, "    }}")?;
    writeln!(
        out,
        "\n    #[must_use]\n    pub const fn asset_name(self) -> Option<&'static str> {{"
    )?;
    out.push_str("        match self.0 {\n");
    for block in &public {
        writeln!(
            out,
            "            {} => Some({:?}),",
            block.id,
            block.asset.as_deref().expect("validated public asset")
        )?;
    }
    out.push_str("            _ => None,\n        }\n    }\n}\n\n");
    out.push_str("pub const PUBLIC_BLOCK_IDS: &[BlockId] = &[\n");
    for block in &public {
        writeln!(out, "    BlockId::{},", screaming(&block.name))?;
    }
    out.push_str("];\n\n");
    if internal.len() == 1 {
        writeln!(
            out,
            "pub const INTERNAL_BLOCK_IDS: &[BlockId] = &[BlockId::{}];",
            screaming(&internal[0].name)
        )?;
    } else {
        out.push_str("pub const INTERNAL_BLOCK_IDS: &[BlockId] = &[\n");
        for block in &internal {
            writeln!(out, "    BlockId::{},", screaming(&block.name))?;
        }
        out.push_str("];\n");
    }
    Ok(out)
}

fn rust_biomes(spec: &BiomesSpec) -> Result<String, Box<dyn Error>> {
    let mut out = String::from(GENERATED_HEADER_RUST);
    out.push_str("use crate::BiomeId;\n\nimpl BiomeId {\n");
    for biome in &spec.biome {
        writeln!(
            out,
            "    pub const {}: Self = Self({});",
            screaming(&biome.name),
            biome.id
        )?;
    }
    writeln!(
        out,
        "\n    #[must_use]\n    pub const fn is_supported(self) -> bool {{"
    )?;
    writeln!(
        out,
        "        matches!(self.0, {})",
        rust_ranges(&spec.biome.iter().map(|b| b.id).collect::<Vec<_>>())
    )?;
    writeln!(out, "    }}")?;
    out.push_str("\n    #[must_use]\n    pub const fn default_color(self) -> Option<u32> {\n        match self.0 {\n");
    for biome in &spec.biome {
        writeln!(
            out,
            "            {} => Some(0x{:06x}),",
            biome.id, biome.color
        )?;
    }
    out.push_str(
        "            _ => None,\n        }\n    }\n}\n\npub const BIOME_IDS: &[BiomeId] = &[\n",
    );
    for biome in &spec.biome {
        writeln!(out, "    BiomeId::{},", screaming(&biome.name))?;
    }
    out.push_str("];\n");
    Ok(out)
}

fn php_target(spec: &RootTargetSpec) -> Result<String, Box<dyn Error>> {
    let mut out = php_header("Cobblestone\\Internal");
    out.push_str(GENERATED_HEADER_PHP);
    out.push_str("\nfinal class Target\n{\n");
    writeln!(
        out,
        "    public const GAME_VERSION = {:?};",
        spec.target.game_version
    )?;
    writeln!(
        out,
        "    public const GAME_PROTOCOL = {};",
        spec.target.game_protocol
    )?;
    writeln!(
        out,
        "    public const RAKNET_PROTOCOL = {};",
        spec.target.raknet_protocol
    )?;
    out.push_str("\n    private function __construct() {}\n}\n");
    Ok(out)
}

fn php_world_bounds(spec: &RootTargetSpec) -> Result<String, Box<dyn Error>> {
    let mut out = php_header("Cobblestone\\World");
    out.push_str(GENERATED_HEADER_PHP);
    out.push_str("\nfinal class WorldBounds\n{\n");
    writeln!(out, "    public const CHUNK_EDGE = {};", spec.chunk.edge)?;
    writeln!(out, "    public const SECTION_EDGE = {};", spec.chunk.edge)?;
    writeln!(
        out,
        "    public const SECTION_COUNT = {};",
        spec.chunk.height / spec.chunk.edge
    )?;
    out.push_str("    public const WORLD_HEIGHT = self::SECTION_EDGE * self::SECTION_COUNT;\n    public const MIN_Y = 0;\n    public const MAX_Y = self::WORLD_HEIGHT - 1;\n\n    private function __construct() {}\n\n    public static function containsY(int $y): bool\n    {\n        return $y >= self::MIN_Y && $y <= self::MAX_Y;\n    }\n\n    public static function containsLocal(int $coordinate): bool\n    {\n        return $coordinate >= 0 && $coordinate < self::CHUNK_EDGE;\n    }\n}\n");
    Ok(out)
}

fn php_block_type(spec: &BlocksSpec) -> Result<String, Box<dyn Error>> {
    let public: Vec<_> = spec.block.iter().filter(|block| block.public).collect();
    let mut out = php_header("Cobblestone\\World");
    out.push_str(GENERATED_HEADER_PHP);
    out.push_str("\nuse Cobblestone\\World\\Internal\\BlockTypeMetadata;\nuse Cobblestone\\World\\Light\\BlockLightProperties;\nuse ValueError;\n\n/**\n * Exact registered block identities for Minecraft: Windows 10 Edition Beta 0.15.10.\n *\n * Backed values are the fixed-target legacy block IDs used by protocol/storage state tokens.\n * Enum cases are singleton semantic identities; no BlockType allocation occurs per lookup.\n */\nenum BlockType: int\n{\n");
    for block in &public {
        writeln!(out, "    case {} = {};", pascal(&block.name), block.id)?;
    }
    out.push_str(
        "\n    public function assetName(): string\n    {\n        return match ($this) {\n",
    );
    for block in &public {
        writeln!(
            out,
            "            self::{} => {:?},",
            pascal(&block.name),
            block.asset.as_deref().expect("validated public asset")
        )?;
    }
    out.push_str("        };\n    }\n\n    public function lightProperties(): BlockLightProperties\n    {\n        return BlockTypeMetadata::lightProperties($this);\n    }\n\n    public function state(BlockData $data = BlockData::Zero): BlockState\n    {\n        return new BlockState($this, $data);\n    }\n\n    public function isAir(): bool\n    {\n        return $this === self::Air;\n    }\n\n    public static function fromAssetName(string $name): self\n    {\n        return self::tryFromAssetName($name)\n            ?? throw new ValueError(\"unsupported fixed-target block name '{$name}'\");\n    }\n\n    public static function tryFromAssetName(string $name): ?self\n    {\n        /** @var array<string, self>|null $byName */\n        static $byName = null;\n\n        if ($byName === null) {\n            $byName = [];\n            foreach (self::cases() as $type) {\n                $byName[$type->assetName()] = $type;\n            }\n        }\n\n        return $byName[$name] ?? null;\n    }\n}\n");
    Ok(out)
}

fn php_biome_id(spec: &BiomesSpec) -> Result<String, Box<dyn Error>> {
    let mut out = php_header("Cobblestone\\World");
    out.push_str(GENERATED_HEADER_PHP);
    out.push_str("\nuse ValueError;\n\nfinal readonly class BiomeId\n{\n");
    for biome in &spec.biome {
        writeln!(
            out,
            "    public const {} = {};",
            screaming(&biome.name),
            biome.id
        )?;
    }
    out.push_str("\n    public function __construct(public int $value)\n    {\n        if (!BiomeCatalog::supports($value)) {\n            throw new ValueError(\"unsupported MCPE 0.15.10 biome id {$value}\");\n        }\n    }\n\n    public function name(): string\n    {\n        return BiomeCatalog::name($this->value);\n    }\n\n    public function defaultColor(): int\n    {\n        return BiomeCatalog::defaultColor($this->value);\n    }\n\n    public function column(): BiomeColumn\n    {\n        return BiomeColumn::forId($this);\n    }\n}\n");
    Ok(out)
}

fn php_biome_catalog(spec: &BiomesSpec) -> Result<String, Box<dyn Error>> {
    let mut out = php_header("Cobblestone\\World");
    out.push_str(GENERATED_HEADER_PHP);
    out.push_str("\n/**\n * Exact registered biome identities for Minecraft: Windows 10 Edition Beta 0.15.10.\n *\n * Colors are the fixed-target default column colors used when generation creates a biome column.\n * Stored biome color remains independent from the biome ID after creation.\n */\nfinal class BiomeCatalog\n{\n    /** @var array<int, array{name: string, color: int}> */\n    private const BIOMES = [\n");
    for biome in &spec.biome {
        writeln!(
            out,
            "        {} => ['name' => {:?}, 'color' => 0x{:06x}],",
            biome.id, biome.display, biome.color
        )?;
    }
    out.push_str("    ];\n\n    private function __construct() {}\n\n    public static function supports(int $id): bool\n    {\n        return isset(self::BIOMES[$id]);\n    }\n\n    public static function name(int $id): string\n    {\n        self::assertSupported($id);\n\n        return self::BIOMES[$id]['name'];\n    }\n\n    public static function defaultColor(int $id): int\n    {\n        self::assertSupported($id);\n\n        return self::BIOMES[$id]['color'];\n    }\n\n    /** @return list<int> */\n    public static function ids(): array\n    {\n        return array_keys(self::BIOMES);\n    }\n\n    private static function assertSupported(int $id): void\n    {\n        if (!self::supports($id)) {\n            throw new \\ValueError(\"unsupported fixed-target biome id {$id}\");\n        }\n    }\n}\n");
    Ok(out)
}

fn php_header(namespace: &str) -> String {
    format!("<?php\n\ndeclare(strict_types=1);\n\nnamespace {namespace};\n\n")
}

fn version_parts(version: &str) -> Result<[u8; 3], Box<dyn Error>> {
    let parts: Vec<_> = version
        .split('.')
        .map(str::parse::<u8>)
        .collect::<Result<_, _>>()?;
    parts
        .try_into()
        .map_err(|_| "target.game_version must have three components".into())
}

fn screaming(name: &str) -> String {
    name.to_ascii_uppercase()
}

fn pascal(name: &str) -> String {
    let mut out = String::new();
    for part in name.split('_') {
        let mut chars = part.chars();
        if let Some(first) = chars.next() {
            out.extend(first.to_uppercase());
            out.extend(chars);
        }
    }
    out
}

fn rust_ranges(ids: &[u8]) -> String {
    let mut parts = Vec::new();
    let mut index = 0;
    while index < ids.len() {
        let start = ids[index];
        let mut end = start;
        while index + 1 < ids.len() && ids[index + 1] == end.saturating_add(1) {
            index += 1;
            end = ids[index];
        }
        if start == end {
            parts.push(start.to_string());
        } else if end == start + 1 {
            parts.push(start.to_string());
            parts.push(end.to_string());
        } else {
            parts.push(format!("{start}..={end}"));
        }
        index += 1;
    }
    parts.join(" | ")
}
